  "claims": [
    {
      "text": "Under the Manual’s practice, if an extension to file evidence in reply is refused, the period allowed for the parties to file evidence concludes.",
      "quotes": [
        {
          "ref": "TMM/Part51/2/2/4",
          "quote": "If the extension was for filing evidence in reply, the period allowed for the parties to file their evidence concludes and the parties will have the opportunity to request a hearing."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The parties then have the opportunity to request a hearing; the Manual records this for both opposition to registration or protection and opposition to removal or cessation of protection.",
      "quotes": [
        {
          "ref": "TMM/Part51/2/2/4",
          "quote": "If the extension was for filing evidence in reply, the period allowed for the parties to file their evidence concludes and the parties will have the opportunity to request a hearing."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "If neither party has requested a hearing, the Manual says the Registrar will write to both sides to give them an opportunity to do so.",
      "quotes": [
        {
          "ref": "TMM/Part51/5#1~1",
          "quote": "If neither party has requested a hearing, the Registrar will write to both sides to give them an opportunity to do so (reg 21.15)."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The Manual states that, once the evidence period has ended, the Registrar must decide the opposition, provided the relevant fees are paid.",
      "quotes": [
        {
          "ref": "TMM/Part51/5#1~1",
          "quote": "Once the period for the parties to serve their evidence has ended the Registrar must decide the opposition (ss 55, 101 and 102 and regs 17A.34N and 17A.48X) provided the relevant fees are paid."
        }
      ],
      "authority": "manual"
    }
  ],
